rss.channel:
    {{ config.title }}
    {{ config.base_url | escape_xml | safe }}
    {{ config.description }}
    Zola
    {{ lang }}

    {% if last_updated is defined %}{{ last_updated | date(format="%a, %d %b %Y %H:%M:%S %z") }}{% endif %}
    {%- for page in items %}
    {%- set section = page.components[0] %}
    {%- set title = page.title %}
    {%- set body = page.content %}
    {%- if section == "reading" %}
      {%- set state = page.taxonomies.readstate?[0] or "" %}
      {%- if state == "queue" %}{% set title = title ~ " (queued)" %}
      {%- elif state == "reading" %}{% set title = title ~ " (reading)" %}{% endif %}
      {%- set citation = (page.taxonomies.authorname?[0] or "") ~ ". (" ~ (page.taxonomies.pubyear?[0] or "") ~ ")." %}
      {%- if page.taxonomies.rating?[0] %}{% set citation = citation ~ " (rated " ~ page.taxonomies.rating[0] ~ "/5)" %}{% endif %}
      {%- if page.taxonomies.recommender?[0] %}{% set citation = citation ~ " (recommended by " ~ page.taxonomies.recommender[0] ~ ")" %}{% endif %}
      {%- set body = "
" ~ citation ~ "" ~ body %}
    {%- endif %}


      {{ title }}
      {{ (page.updated or page.date) | date(format="%a, %d %b %Y %H:%M:%S %z") }}
      {{ config.extra.author }}
      {{ section }}
      {{ page.permalink | escape_xml | safe }}
      {{ page.permalink | escape_xml | safe }}
      {{ body | replace(from='src="/', to=abs_src) | replace(from='href="/', to=abs_href) }}

    {%- endfor %}
